"""Wire samples for the API Keys page, generated by the converters.

A sample that has drifted from the converter is worse than no sample: the
operator copies it, and the gateway answers 400.  So the body of every
sample is produced by the same converter the gateway runs, from a canonical
IR request.  Only the parts the gateway owns are written here — the
client-facing path, the auth header, the content type.

The paths come from the format catalog: a chat format carries its own
``route_path``, and a format whose model travels in the URL carries it in
``url_template`` (the gateway forwards that route verbatim); the typed
formats carry ``default_path``.
"""

from __future__ import annotations

import copy
import logging
from typing import Any

from llm_rosetta_gateway._vendor.httpserver import JSONResponse, Response
from llm_rosetta.formats.catalog import FORMAT_SPECS, MODEL_TYPES
from llm_rosetta.formats.spec import FormatSpec

from ._shared import _qp

logger = logging.getLogger("llm-rosetta-gateway")

#: How a client presents the gateway key for a wire family.  The value holds
#: ``{key}`` where the secret goes; the panel substitutes the expression its
#: language needs.  These mirror ``middleware.auth._extract_key``: a client
#: that copies the sample presents the key the way the gateway reads it.
_AUTH_HEADERS: dict[str, dict[str, str]] = {
    "openai": {"name": "Authorization", "value": "Bearer {key}"},
    "anthropic": {"name": "x-api-key", "value": "{key}"},
    "google": {"name": "x-goog-api-key", "value": "{key}"},
}

#: A format with no declared wire family accepts a bearer token, which is
#: what ``_extract_key`` falls back to.
_DEFAULT_WIRE_FAMILY = "openai"

#: The model identifier inside a catalog path template.
_MODEL_SLOT = "{model}"

#: The rail's model-type order, which is the order the groups appear in.
MODEL_TYPE_ORDER = {name: i for i, name in enumerate(MODEL_TYPES)}


def _llm_ir(model: str) -> dict[str, Any]:
    return {
        "model": model,
        "messages": [{"role": "user", "content": [{"type": "text", "text": "Hello"}]}],
        "generation": {"max_tokens": 64},
    }


def _embedding_ir(model: str) -> dict[str, Any]:
    return {"model": model, "input": ["Hello"]}


def _rerank_ir(model: str) -> dict[str, Any]:
    return {
        "model": model,
        "query": "What is Python?",
        "documents": [
            {"text": "Python is a programming language."},
            {"text": "A python is a large snake."},
        ],
    }


def _decision_ir(model: str) -> dict[str, Any]:
    return {
        "model": model,
        "state": "The parcel arrived on time and works as advertised.",
        "questions": {
            "sentiment": {
                "type": "choice",
                "instructions": "Overall sentiment of the review",
                "criteria": [{"label": "positive"}, {"label": "negative"}],
            }
        },
    }


_IR_BUILDERS = {
    "llm": _llm_ir,
    "embeddings": _embedding_ir,
    "rerank": _rerank_ir,
    "decisions": _decision_ir,
}


def _converter(spec: FormatSpec) -> Any:
    """Return the converter that writes ``spec``'s wire format."""
    if spec.model_type == "llm":
        from llm_rosetta import get_converter_for_provider

        return get_converter_for_provider(spec.format)
    if spec.model_type == "embeddings":
        from llm_rosetta.converters.embeddings import get_embedding_converter

        return get_embedding_converter(spec.format)
    if spec.model_type == "rerank":
        from llm_rosetta.converters.rerank import get_rerank_converter

        return get_rerank_converter(spec.format)
    from llm_rosetta.converters.decisions import get_decision_converter

    return get_decision_converter(spec.format)


def _client_path(spec: FormatSpec, model: str) -> str | None:
    """The URL the operator calls on *this* gateway for ``spec``.

    A chat format's ``route_path`` is the gateway's own route.  When the
    route carries the model (Google's ``/v1beta/models/...``), the concrete
    operation lives in ``url_template`` instead, and the gateway forwards
    the path it was given — so the sample uses that path with the model
    filled in.
    """
    if spec.model_type == "llm":
        route = spec.route_path
        if not route:
            return None
        if "model_path" in route:
            template = spec.url_template or ""
            base_len = len("{base_url}")
            return template[base_len:].replace(_MODEL_SLOT, model)
        return route
    if not spec.default_path:
        return None
    return spec.default_path.replace(_MODEL_SLOT, model)


def _body_for(spec: FormatSpec, model: str) -> tuple[dict[str, Any], list[str]]:
    """Convert the canonical IR request into ``spec``'s wire body."""
    ir = copy.deepcopy(_IR_BUILDERS[spec.model_type](model))
    body, warnings = _converter(spec).request_to_provider(ir)
    body = dict(body)
    # A Google route carries the model in the path; a client does not repeat
    # it in the body, and the gateway reads it from the URL.
    if spec.wire_family == "google":
        body.pop("model", None)
    return body, list(warnings or [])


def _example(spec: FormatSpec, model: str) -> dict[str, Any] | None:
    path = _client_path(spec, model)
    if path is None:
        return None
    try:
        body, warnings = _body_for(spec, model)
    except Exception as exc:  # a sample must never take the page down
        logger.warning("No sample for %s/%s: %s", spec.model_type, spec.format, exc)
        return None
    family = spec.wire_family or _DEFAULT_WIRE_FAMILY
    return {
        "format": spec.format,
        "path": path,
        "auth": dict(_AUTH_HEADERS.get(family, _AUTH_HEADERS[_DEFAULT_WIRE_FAMILY])),
        "content_type": "application/json",
        "body": body,
        "warnings": warnings,
    }


#: The model id a sample carries: a template the operator replaces, because
#: the panel is static and must not depend on what this deployment configured.
MODEL_PLACEHOLDER = "<model-id>"


async def get_key_examples(request: Any) -> Response:
    """Return one ready-to-run sample per format the gateway speaks.

    With no query the samples are templates: every format of every model
    type, with ``<model-id>`` where the id goes, so the page can show them for a
    deployment that has no model of that type configured.  ``model=`` fills a
    real id instead, and ``type=`` narrows the list to one model type.
    """
    model = _qp(request, "model", "") or MODEL_PLACEHOLDER
    only = _qp(request, "type", "") or None

    specs = [s for s in FORMAT_SPECS if only is None or s.model_type == only]
    specs.sort(key=lambda s: (MODEL_TYPE_ORDER.get(s.model_type, 99), s.picker_order))
    examples = []
    for spec in specs:
        ex = _example(spec, model)
        if ex is not None:
            ex["model_type"] = spec.model_type
            examples.append(ex)
    return JSONResponse({"model": model, "examples": examples})


__all__ = ["get_key_examples"]
